def load() -> pd.DataFrame:
    import pandas as pd
    path = 'data/biomedical/input/1-s2.0-S0092867420301070-mmc3.xlsx'
    xl = pd.ExcelFile(path)
    sheets = xl.sheet_names
    rows = []
    for sh in sheets:
        df = xl.parse(sh)
        rows.append({
            'sheet': sh,
            'nrows': df.shape[0],
            'ncols': df.shape[1],
            'columns': list(df.columns)[:20]
        })
    return pd.DataFrame(rows)

